def _parse_hex_color(value):
    s = value.lstrip("#")
    if len(s) == 3:
        return tuple(int(c * 2, 16) for c in s)
    if len(s) == 6:
        return (int(s[0:2], 16), int(s[2:4], 16), int(s[4:6], 16))
    if len(s) == 12:
        return (int(s[0:4], 16) // 256, int(s[4:8], 16) // 256, int(s[8:12], 16) // 256)
    raise ValueError(value)


def _rgb_of(color):
    if color is None or color == "":
        raise TclError("unknown color name \"\"")
    if isinstance(color, (tuple, list)) and len(color) == 3:
        return tuple(int(c) for c in color)
    name = str(color).strip().lower()
    if name.startswith("#"):
        try:
            return _parse_hex_color(name)
        except Exception:
            raise TclError("unknown color name \"%s\"" % color)
    if name in _NAMED_COLORS:
        return _NAMED_COLORS[name]
    raise TclError("unknown color name \"%s\"" % color)


class PhotoImage(object):
    def __init__(self, name=None, cnf=None, master=None, **kw):
        cnf = dict(cnf or {})
        cnf.update(kw)
        self.file = cnf.get("file") or kw.get("file")
        self._width = int(cnf.get("width") or kw.get("width") or 1)
        self._height = int(cnf.get("height") or kw.get("height") or 1)
        self._blank = not self.file

    def blank(self):
        self._blank = True
        self.file = None

    def width(self):
        return self._width

    def height(self):
        return self._height


class Event(object):
    def __init__(self, x=0, y=0, keysym="", char="", num=1):
        self.x = x
        self.y = y
        self.keysym = keysym
        self.char = char
        self.num = num
        self.type = ""


class _Timer(object):
    def __init__(self, delay_ms, callback):
        self.when = time.time() + max(0, delay_ms) / 1000.0
        self.callback = callback
        self.cancelled = False


_protocol_lock = threading.Lock()
_reply_events = {}
_reply_values = {}
_stdin_buffer = ""
_step_event = threading.Event()
_stop_flag = False
_cancel_flag = False
_stdin_closed = False
_canvas_ref = []
_app_commands = queue.Queue()


def _emit(payload):
    line = "FVT " + json.dumps(payload, separators=(",", ":"), ensure_ascii=False)
    with _protocol_lock:
        sys.stdout.write(line + "\n")
        sys.stdout.flush()


def clear_cancel():
    global _cancel_flag
    _cancel_flag = False


def cancelled():
    return _cancel_flag or _stop_flag


def wait_app_command():
    """Block until the IDE sends a session command (RUN / RESET / QUIT)."""
    _ensure_reader()
    while True:
        try:
            return _app_commands.get(timeout=0.05)
        except queue.Empty:
            if _stop_flag or _stdin_closed:
                raise SystemExit(0)


def wait_step():
    _step_event.clear()
    _emit({"op": "step_wait"})
    while not _stop_flag:
        if _cancel_flag:
            raise SystemExit(0)
        if _step_event.wait(0.05):
            _step_event.clear()
            if _cancel_flag or _stop_flag:
                raise SystemExit(0)
            return
        _pump_stdin(0)


def _handle_control_line(text):
    global _stop_flag, _cancel_flag
    raw = text.strip()
    if not raw:
        return
    upper = raw.upper()
    if upper in ("QUIT", "EXIT"):
        _stop_flag = True
        _cancel_flag = True
        _step_event.set()
        raise SystemExit(0)
    if upper == "STOP":
        _cancel_flag = True
        _step_event.set()
        return
    if upper == "STEP":
        _step_event.set()
        return
    if raw.startswith("REPLY "):
        try:
            data = json.loads(raw[6:])
        except Exception:
            return
        rid = str(data.get("id", ""))
        _reply_values[rid] = data.get("value", None)
        ev = _reply_events.get(rid)
        if ev:
            ev.set()
        return
    if raw.startswith("EVENT "):
        try:
            data = json.loads(raw[6:])
        except Exception:
            return
        for cv in list(_canvas_ref):
            cv._dispatch_event(data)
        return
    _app_commands.put(raw)


def _pump_stdin(timeout):
    global _stdin_buffer
    if timeout and timeout > 0:
        # Non-blocking-ish: read if data already present; otherwise sleep.
        try:
            import msvcrt
            end = time.time() + timeout
            while time.time() < end:
                while msvcrt.kbhit():
                    ch = msvcrt.getwche() if False else None
                    break
                # QProcess pipes are not console — kbhit won't see them.
                break
        except Exception:
            pass
    # Blocking readline with a short select-like approach isn't portable on Win7
    # pipes from QProcess. Use a dedicated reader thread.
    time.sleep(min(timeout or 0, 0.01) if timeout else 0)


_reader_started = False
_reader_lock = threading.Lock()


def _ensure_reader():
    global _reader_started
    with _reader_lock:
        if _reader_started:
            return
        _reader_started = True

        def _loop():
            global _stdin_closed, _stop_flag
            while not _stop_flag:
                line = sys.stdin.readline()
                if not line:
                    _stdin_closed = True
                    return
                try:
                    _handle_control_line(line)
                except SystemExit:
                    _stop_flag = True
                    return
                except Exception:
                    pass

        t = threading.Thread(target=_loop, name="fvt-stdin")
        t.daemon = True
        t.start()


def ask_input(kind, title, prompt, default=None, minval=None, maxval=None):
    _ensure_reader()
    rid = str(time.time())
    ev = threading.Event()
    _reply_events[rid] = ev
    payload = {
        "op": "input",
        "id": rid,
        "kind": kind,
        "title": title or "",
        "prompt": prompt or "",
    }
    if default is not None:
        payload["default"] = default
    if minval is not None:
        payload["min"] = minval
    if maxval is not None:
        payload["max"] = maxval
    _emit(payload)
    while not ev.wait(0.05):
        if _stop_flag or _cancel_flag:
            raise SystemExit(0)
    _reply_events.pop(rid, None)
    return _reply_values.pop(rid, None)


def askstring(title, prompt, parent=None, **kw):
    return ask_input("text", title, prompt)


def askfloat(title, prompt, parent=None, initialvalue=None, minvalue=None, maxvalue=None, **kw):
    return ask_input("float", title, prompt, initialvalue, minvalue, maxvalue)


def askinteger(title, prompt, parent=None, initialvalue=None, minvalue=None, maxvalue=None, **kw):
    return ask_input("int", title, prompt, initialvalue, minvalue, maxvalue)


class _Widget(object):
    def __init__(self, master=None, **kw):
        self.master = master
        self.tk = master.tk if (master is not None and hasattr(master, "tk")) else master
        self.children = []
        if master is not None and hasattr(master, "children"):
            master.children.append(self)
        self._cfg = dict(kw)

    def winfo_toplevel(self):
        w = self
        while getattr(w, "master", None) is not None:
            w = w.master
        return w

    def winfo_id(self):
        return id(self)

    def pack(self, *args, **kw):
        pass

    def grid(self, *args, **kw):
        pass

    def grid_forget(self):
        pass

    def rowconfigure(self, *args, **kw):
        pass

    def columnconfigure(self, *args, **kw):
        pass

    def configure(self, cnf=None, **kw):
        if cnf:
            for k, v in dict(cnf).items():
                if v is not None:
                    self._cfg[k] = v
        for k, v in kw.items():
            if v is not None:
                self._cfg[k] = v

    config = configure

    def cget(self, key):
        return self._cfg.get(key)

    def __getitem__(self, key):
        return self.cget(key)

    def __setitem__(self, key, value):
        self._cfg[key] = value

    def destroy(self):
        pass

    def bind(self, sequence, func=None, add=None):
        pass

    def unbind(self, sequence, funcid=None):
        pass

    def focus_force(self):
        pass


class Scrollbar(_Widget):
    def set(self, *args):
        pass


class Frame(_Widget):
    pass


class Canvas(_Widget):
    _next_id = 1

    def __init__(self, master=None, width=400, height=300, **kw):
        try:
            w = int(float(width))
        except Exception:
            w = 400
        try:
            h = int(float(height))
        except Exception:
            h = 300
        if w < 2:
            w = int(os.environ.get("VUZHYK_FVT_WIDTH", "400"))
        if h < 2:
            h = int(os.environ.get("VUZHYK_FVT_HEIGHT", "400"))
        _Widget.__init__(self, master, width=w, height=h, **kw)
        self.canvwidth = int(kw.get("canvwidth") or w)
        self.canvheight = int(kw.get("canvheight") or h)
        self._cfg.setdefault("bg", kw.get("bg", "white"))
        self._cfg["width"] = w
        self._cfg["height"] = h
        self._items = {}
        self._order = []
        self._bindings = {}
        self._tag_bindings = {}
        self._timers = []
        self._scrollregion = (-self.canvwidth // 2, -self.canvheight // 2,
                              self.canvwidth // 2, self.canvheight // 2)
        self._cfg["scrollregion"] = self._scrollregion
        if self not in _canvas_ref:
            _canvas_ref.append(self)
        _ensure_reader()

    def _new_id(self):
        Canvas._next_id += 1
        return Canvas._next_id

    def _flatten_coords(self, args):
        coords = []
        i = 0
        while i < len(args):
            a = args[i]
            if isinstance(a, (int, float)):
                coords.append(float(a))
                i += 1
            elif isinstance(a, (tuple, list)):
                if a and isinstance(a[0], (tuple, list)):
                    for pt in a:
                        coords.extend(float(x) for x in pt[:2])
                else:
                    coords.extend(float(x) for x in a)
                i += 1
            else:
                break
        return coords, args[i:]

    def _make_item(self, typ, args, extra_kw=None):
        coords, rest = self._flatten_coords(args)
        kw = dict(extra_kw or {})
        # remaining should be empty; kwargs already in extra_kw
        item_id = self._new_id()
        item = {
            "id": item_id,
            "type": typ,
            "coords": coords,
            "opts": kw,
            "tags": set(),
        }
        tag = kw.get("tags")
        if tag:
            if isinstance(tag, (list, tuple)):
                item["tags"].update(tag)
            else:
                item["tags"].add(tag)
        self._items[item_id] = item
        self._order.append(item_id)
        return item_id

    def create_line(self, *args, **kw):
        return self._make_item("line", args, kw)

    def create_polygon(self, *args, **kw):
        return self._make_item("polygon", args, kw)

    def create_text(self, *args, **kw):
        return self._make_item("text", args, kw)

    def create_image(self, *args, **kw):
        return self._make_item("image", args, kw)

    def coords(self, item, *args):
        it = self._items.get(int(item))
        if it is None:
            return []
        if args:
            coords, _ = self._flatten_coords(args)
            if len(args) == 1 and isinstance(args[0], (tuple, list)):
                coords, _ = self._flatten_coords(args)
            it["coords"] = coords
            return coords
        return list(it["coords"])

    def itemconfigure(self, item, cnf=None, **kw):
        it = self._items.get(int(item))
        if it is None:
            return
        if cnf:
            it["opts"].update(cnf)
        it["opts"].update(kw)

    itemconfig = itemconfigure

    def delete(self, item):
        if item == "all":
            self._items.clear()
            self._order = []
            return
        iid = int(item)
        self._items.pop(iid, None)
        self._order = [x for x in self._order if x != iid]

    def tag_raise(self, item):
        iid = int(item)
        if iid in self._order:
            self._order.remove(iid)
            self._order.append(iid)

    def tag_lower(self, item):
        iid = int(item)
        if iid in self._order:
            self._order.remove(iid)
            self._order.insert(0, iid)

    def addtag_withtag(self, newtag, item):
        it = self._items.get(int(item))
        if it is not None:
            it["tags"].add(newtag)

    def find_all(self):
        return tuple(self._order)

    def find_withtag(self, tag):
        if tag == "all":
            return self.find_all()
        found = []
        for iid in self._order:
            if tag in self._items[iid]["tags"]:
                found.append(iid)
        return tuple(found)

    def type(self, item):
        it = self._items.get(int(item))
        return it["type"] if it else None

    def bbox(self, item):
        it = self._items.get(int(item))
        if it is None:
            return (0, 0, 0, 0)
        coords = it["coords"]
        if it["type"] == "text" and len(coords) >= 2:
            text = str(it["opts"].get("text", ""))
            font = it["opts"].get("font") or ("Arial", 8)
            size = 8
            if isinstance(font, (tuple, list)) and len(font) >= 2:
                try:
                    size = int(font[1])
                except Exception:
                    size = 8
            w = max(6, int(len(text) * size * 0.6))
            h = max(size + 4, 10)
            x, y = coords[0], coords[1]
            return (x, y - h, x + w, y)
        if len(coords) < 2:
            return (0, 0, 0, 0)
        xs = coords[0::2]
        ys = coords[1::2]
        return (min(xs), min(ys), max(xs), max(ys))

    def canvasx(self, x, gridspacing=None):
        w = float(self._cfg.get("width") or self.canvwidth)
        return float(x) - w / 2.0

    def canvasy(self, y, gridspacing=None):
        h = float(self._cfg.get("height") or self.canvheight)
        return float(y) - h / 2.0

    def winfo_rgb(self, color):
        r, g, b = _rgb_of(color)
        return (r * 257, g * 257, b * 257)

    def winfo_width(self):
        return int(self._cfg.get("width") or self.canvwidth)

    def winfo_height(self):
        return int(self._cfg.get("height") or self.canvheight)

    def configure(self, cnf=None, **kw):
        _Widget.configure(self, cnf, **kw)
        if "scrollregion" in (cnf or {}) or "scrollregion" in kw:
            sr = (cnf or {}).get("scrollregion", kw.get("scrollregion"))
            if sr:
                self._scrollregion = tuple(sr)
        if "width" in kw:
            self.canvwidth = int(kw["width"])
        if "height" in kw:
            self.canvheight = int(kw["height"])

    config = configure

    def xview(self, *args):
        return (0.0, 1.0)

    def yview(self, *args):
        return (0.0, 1.0)

    def xview_moveto(self, *args):
        pass

    def yview_moveto(self, *args):
        pass

    def tag_bind(self, item, sequence, func, add=None):
        self._tag_bindings.setdefault(int(item), {}).setdefault(sequence, [])
        if add:
            self._tag_bindings[int(item)][sequence].append(func)
        else:
            self._tag_bindings[int(item)][sequence] = [func]

    def tag_unbind(self, item, sequence, funcid=None):
        binds = self._tag_bindings.get(int(item))
        if binds:
            binds.pop(sequence, None)

    def bind(self, sequence, func=None, add=None):
        if func is None:
            return
        self._bindings.setdefault(sequence, [])
        if add:
            self._bindings[sequence].append(func)
        else:
            self._bindings[sequence] = [func]

    def unbind(self, sequence, funcid=None):
        self._bindings.pop(sequence, None)

    def after(self, ms, func=None, *args):
        if func is None:
            self._sleep(ms)
            return None
        timer = _Timer(ms, lambda: func(*args))
        self._timers.append(timer)
        return timer

    def after_idle(self, func, *args):
        return self.after(0, func, *args)

    def after_cancel(self, timer):
        if timer is not None:
            timer.cancelled = True

    def _sleep(self, ms):
        end = time.time() + max(0, int(ms)) / 1000.0
        while time.time() < end:
            if _stop_flag or _cancel_flag:
                raise SystemExit(0)
            self._fire_timers()
            time.sleep(0.01)

    def _fire_timers(self):
        now = time.time()
        due = [t for t in self._timers if (not t.cancelled) and t.when <= now]
        self._timers = [t for t in self._timers if (not t.cancelled) and t.when > now]
        for t in due:
            try:
                t.callback()
            except SystemExit:
                raise
            except Exception:
                pass

    def _item_to_json(self, item):
        opts = item["opts"]
        image = opts.get("image")
        image_path = ""
        if image is not None and getattr(image, "file", None):
            image_path = image.file
        font = opts.get("font")
        family, size, weight = "Arial", 8, "normal"
        if isinstance(font, str):
            family = font
        elif isinstance(font, (tuple, list)):
            if font:
                family = str(font[0])
            if len(font) > 1:
                try:
                    size = int(font[1])
                except Exception:
                    size = 8
            if len(font) > 2:
                weight = str(font[2])
        return {
            "id": item["id"],
            "type": item["type"],
            "coords": item["coords"],
            "fill": opts.get("fill", ""),
            "outline": opts.get("outline", ""),
            "width": opts.get("width", opts.get("penwidth", 1)),
            "capstyle": opts.get("capstyle", "round"),
            "text": opts.get("text", ""),
            "anchor": opts.get("anchor", "center"),
            "fontFamily": family,
            "fontSize": size,
            "fontWeight": weight,
            "image": image_path,
            "tags": list(item["tags"]),
        }

    def _scene_payload(self):
        items = []
        for iid in self._order:
            it = self._items.get(iid)
            if it is not None:
                items.append(self._item_to_json(it))
        return {
            "op": "scene",
            "w": int(self._cfg.get("width") or self.canvwidth),
            "h": int(self._cfg.get("height") or self.canvheight),
            "bg": self._cfg.get("bg", "white"),
            "items": items,
        }

    def update(self):
        if _stop_flag or _cancel_flag:
            raise SystemExit(0)
        self._fire_timers()
        _emit(self._scene_payload())

    def update_idletasks(self):
        self.update()

    def reset(self, canvwidth=None, canvheight=None, bg=None):
        if canvwidth is not None:
            self.canvwidth = int(canvwidth)
            self._cfg["width"] = int(canvwidth)
        if canvheight is not None:
            self.canvheight = int(canvheight)
            self._cfg["height"] = int(canvheight)
        if bg is not None:
            self._cfg["bg"] = bg
        self._scrollregion = (-self.canvwidth // 2, -self.canvheight // 2,
                              self.canvwidth // 2, self.canvheight // 2)
        self.update()

    def _dispatch_event(self, data):
        typ = data.get("type")
        ev = Event(
            x=data.get("x", 0),
            y=data.get("y", 0),
            keysym=data.get("key", ""),
            char=data.get("char", ""),
            num=data.get("button", 1),
        )
        sequences = []
        if typ == "click":
            sequences.append("<Button-%s>" % ev.num)
        elif typ == "release":
            sequences.append("<Button%s-ButtonRelease>" % ev.num)
        elif typ == "drag":
            sequences.append("<Button%s-Motion>" % ev.num)
        elif typ == "move":
            sequences.append("<Motion>")
        elif typ == "leave":
            sequences.append("<Leave>")
        elif typ == "key":
            sequences.append("<KeyPress>")
            if ev.keysym:
                sequences.append("<KeyPress-%s>" % ev.keysym)
                sequences.append("<KeyRelease-%s>" % ev.keysym)
        for seq in sequences:
            for fun in list(self._bindings.get(seq, [])):
                try:
                    fun(ev)
                except Exception:
                    pass
            for iid, binds in list(self._tag_bindings.items()):
                for fun in list(binds.get(seq, [])):
                    try:
                        fun(ev)
                    except Exception:
                        pass

    def mainloop(self, n=0):
        _ensure_reader()
        self.update()
        while not _stop_flag and not _stdin_closed:
            self._fire_timers()
            time.sleep(0.02)
        if _stop_flag:
            raise SystemExit(0)


class Tk(_Widget):
    def __init__(self, screenName=None, baseName=None, className="Tk", **kw):
        _Widget.__init__(self, None)
        self.tk = self
        self._canvas = None
        self._title = "Python Turtle Graphics"
        self._on_destroy = None
        w = int(os.environ.get("VUZHYK_FVT_WIDTH", "400"))
        h = int(os.environ.get("VUZHYK_FVT_HEIGHT", "400"))
        self._screen_w = max(w, 200)
        self._screen_h = max(h, 200)

    def title(self, text=None):
        if text is not None:
            self._title = text
            _emit({"op": "title", "text": text})
        return self._title

    def setupcanvas(self, width, height, cwidth, cheight):
        self._canvas = ScrolledCanvas(self, width, height, cwidth, cheight)
        return self._canvas

    def _getcanvas(self):
        return self._canvas

    def set_geometry(self, width, height, startx, starty):
        self._screen_w = int(width)
        self._screen_h = int(height)
        if self._canvas is not None:
            self._canvas._cfg["width"] = int(width)
            self._canvas._cfg["height"] = int(height)
            _emit({"op": "resize", "w": int(width), "h": int(height)})

    def geometry(self, spec=None):
        pass

    def wm_protocol(self, name, func=None):
        if name == "WM_DELETE_WINDOW":
            self._on_destroy = func

    def ondestroy(self, destroy):
        self._on_destroy = destroy

    def win_width(self):
        return int(os.environ.get("VUZHYK_FVT_SCREEN_W", "1920"))

    def win_height(self):
        return int(os.environ.get("VUZHYK_FVT_SCREEN_H", "1080"))

    def winfo_screenwidth(self):
        return int(os.environ.get("VUZHYK_FVT_SCREEN_W", "1920"))

    def winfo_screenheight(self):
        return int(os.environ.get("VUZHYK_FVT_SCREEN_H", "1080"))

    def mainloop(self, n=0):
        if self._canvas is not None:
            self._canvas.mainloop(n)
        else:
            _ensure_reader()
            while not _stop_flag and not _stdin_closed:
                time.sleep(0.05)

    def destroy(self):
        global _stop_flag
        _stop_flag = True
        if self._on_destroy:
            try:
                self._on_destroy()
            except Exception:
                pass


class ScrolledCanvas(Canvas):
    def __init__(self, master, width=500, height=350, canvwidth=600, canvheight=500):
        Canvas.__init__(self, master, width=int(canvwidth), height=int(canvheight),
                        bg="white")
        self._rootwindow = self.winfo_toplevel()
        self.width = int(width) if not isinstance(width, float) else int(canvwidth)
        self.height = int(height) if not isinstance(height, float) else int(canvheight)
        self.canvwidth = int(canvwidth)
        self.canvheight = int(canvheight)
        self.bg = "white"
        self._canvas = self
        self.hscroll = Scrollbar(master)
        self.vscroll = Scrollbar(master)
        env_w = os.environ.get("VUZHYK_FVT_WIDTH")
        env_h = os.environ.get("VUZHYK_FVT_HEIGHT")
        if env_w:
            self.canvwidth = int(env_w)
            self._cfg["width"] = self.canvwidth
        if env_h:
            self.canvheight = int(env_h)
            self._cfg["height"] = self.canvheight
        self._scrollregion = (-self.canvwidth // 2, -self.canvheight // 2,
                              self.canvwidth // 2, self.canvheight // 2)

    def onResize(self, event):
        pass

    def adjustScrolls(self):
        pass
